let mocha = require('mocha');
let assert = require('assert');
let zod = require('zod');

describe('test zod', function() {
    it('test zod.z.guid', function(done) {
        // Obtain the schema generated by zod.z.guid()
        const guidSchema = zod.z.guid();

        // The schema should be a JSON‑Schema style object with type "string" and format "uuid"
        assert.strictEqual(guidSchema.type, 'string', 'type should be string');
        assert.strictEqual(guidSchema.format, 'uuid', 'format should be uuid');

        // Verify that a typical UUID string matches the expected GUID pattern
        const guidPattern = /^[0-9a-fA-F]{8}(-[0-9a-fA-F]{4}){3}-[0-9a-fA-F]{12}$/;
        const exampleGuid = '123e4567-e89b-12d3-a456-426614174000';
        assert.ok(guidPattern.test(exampleGuid), 'example GUID should match the pattern');

        done();
    });
});